"""Appendix A.5 source-data gate. Inputs are NEVER generated by this checker.
Use --demo for one synthetic passing and failing example; no proof of NS.
"""
import argparse,json
from fractions import Fraction as F
def frac(s):return F(str(s))
def audit(inp):
    lam=frac(inp["lambda"]);h=frac(inp["h"])
    c=frac(inp["axial_bump_coeff_abs_upper"])
    dw=frac(inp["w_main_approx_error_upper"])
    q=frac(inp["Qs_lower"]);x=frac(inp["X_lower"])
    if min(lam,h,q,x)<=0 or min(c,dw)<0:raise ValueError("positive inputs")
    amp=F(1011,1000)
    db=2*lam*(amp*11+amp*705)+(1+2*lam)*F(1280,3)*c+800000*c
    cross=1500*db+12*dw+db*dw
    second=2*cross+(24*db+db**2)/2+2*lam*(3000*dw+dw**2)
    cd=F(1,2)*lam/(lam-h)/(F(1,2)-lam)**2 if h<lam else None
    b1=F(74,100)-F(58081,80000)-cross
    b2=F(168,100)-F(58081,35000)-2*lam*1500**2-second
    good=(lam<=F(1,2_000_000_000) and h<=lam/10000
          and c<=lam/400000 and db<=F(1,10**6)
          and dw<=F(1,10**6) and cd is not None
          and cd<=F(2001,1000) and x*q>=F(9,2)
          and b1>0 and b2>0)
    return {"status":"CONDITIONAL_ALGEBRA_PASS" if good else "UNRESOLVED",
            "source_inputs_verified":False,"shear_error_upper":str(db),
            "first_margin_lower":str(b1),"second_margin_lower":str(b2),
            "required":"independent source A.29-A.30 w interval, A.9 axial coefficients, amplitude and Q/X intervals"}
if __name__=="__main__":
    p=argparse.ArgumentParser();p.add_argument("--demo",action="store_true")
    p.add_argument("data",nargs="?");a=p.parse_args()
    if a.demo:
        sample={"lambda":"1/2000000000","h":"1/20000000000000",
                "axial_bump_coeff_abs_upper":"1/800000000000000",
                "w_main_approx_error_upper":"1/1000000",
                "Qs_lower":"1/2000000000","X_lower":"10000000000"}
        assert audit(sample)["status"]=="CONDITIONAL_ALGEBRA_PASS"
        sample["w_main_approx_error_upper"]="1"
        assert audit(sample)["status"]=="UNRESOLVED"
        print("PASS synthetic positive/negative controls; NO source verification")
    else:
        if not a.data:p.error("Use --demo or source-certified input JSON")
        print(json.dumps(audit(json.load(open(a.data))),indent=2))
